// Normalizes rows from any bank / card CSV export into one clean shape.
const cfg = $('Config').first().json;
const dmy = String(cfg.dateFormat || 'DMY').toUpperCase() === 'DMY';
const debitsNegative = cfg.debitsAreNegative === true || String(cfg.debitsAreNegative).toLowerCase() === 'true';

const pick = (row, names) => {
  const keys = Object.keys(row);
  for (const n of names) {
    const k = keys.find(k => k.toLowerCase().replace(/[^a-z]/g, '') === n);
    if (k !== undefined && row[k] !== '' && row[k] != null) return row[k];
  }
  return null;
};
const toNum = v => {
  if (v == null) return NaN;
  let s = String(v).trim();
  const neg = /^\(.*\)$/.test(s) || /^-/.test(s) || /\bcr\b/i.test(s);
  s = s.replace(/[^0-9.]/g, '');
  const n = parseFloat(s);
  if (isNaN(n)) return NaN;
  return neg ? -n : n;
};
const parseDate = v => {
  if (!v) return null;
  const s = String(v).trim();
  const m = s.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2,4})/);
  if (m) {
    let [, a, b, y] = m;
    if (y.length === 2) y = '20' + y;
    const day = dmy ? a : b, mon = dmy ? b : a;
    const d = new Date(Date.UTC(+y, +mon - 1, +day));
    return isNaN(d) ? null : d.toISOString().slice(0, 10);
  }
  const d = new Date(s);
  return isNaN(d) ? null : d.toISOString().slice(0, 10);
};
const STOP = /\b(inc|llc|ltd|pvt|private|limited|corp|co|com|net|io|www|subscription|subscr|recurring|bill|billing|payment|purchase|pos|ach|upi|nach|ecom|online|intl|international|monthly|annual|charge)\b/g;
const cleanMerchant = s => String(s || '').toLowerCase()
  .replace(/[*#_\/\\.,:;()\-]+/g, ' ')
  .replace(/\d{3,}/g, ' ')
  .replace(STOP, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const out = [];
for (const item of $input.all()) {
  const row = item.json || {};
  if (row.error || !Object.keys(row).length) continue;
  const desc = pick(row, ['description','merchant','merchantname','narration','details','transactiondetails','payee','name','particulars','remarks']);
  let amt = toNum(pick(row, ['debit','debitamount','withdrawal','withdrawalamt','withdrawalamount','amount','transactionamount','amountinr','amountusd','billingamount']));
  const date = parseDate(pick(row, ['date','transactiondate','txndate','posteddate','postingdate','valuedate','transdate']));
  if (!desc || isNaN(amt)) continue;
  if (debitsNegative) amt = -amt;
  if (amt <= 0) continue; // skip refunds / credits
  out.push({ json: {
    source: 'card',
    date: date || '',
    month: date ? date.slice(0, 7) : '',
    merchantRaw: String(desc).trim(),
    merchant: cleanMerchant(desc),
    amount: Math.round(amt * 100) / 100
  }});
}
return out;

// Bundles all invoice/receipt emails into ONE item so the AI is called once.
const strip = h => String(h || '')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/\s+/g, ' ')
  .trim();

const emails = $input.all().map(i => i.json).filter(e => e && e.id);
const batch = emails.slice(0, 80).map(e => ({
  id: e.id,
  from: e.from?.value?.[0]?.address || e.from?.text || '',
  fromName: e.from?.value?.[0]?.name || '',
  subject: e.subject || '',
  date: e.date || '',
  body: (e.text || strip(e.html) || e.snippet || '').replace(/\s+/g, ' ').slice(0, 900)
}));
return [{ json: { emailCount: batch.length, emails: batch } }];

