// Turns the AI extraction into one item per SaaS invoice.
const raw = $input.first()?.json || {};
let content = raw?.message?.content ?? raw?.content ?? raw?.text ?? {};
if (typeof content === 'string') {
  try { content = JSON.parse(content.replace(/```json|```/g, '').trim()); } catch (e) { content = {}; }
}
const list = Array.isArray(content?.invoices) ? content.invoices : [];
return list
  .filter(i => i && i.vendor && i.is_saas_subscription !== false)
  .map(i => ({ json: {
    source: 'invoice',
    emailId: i.email_id || '',
    vendor: String(i.vendor).trim(),
    product: i.product || '',
    amount: Math.abs(parseFloat(i.amount) || 0),
    currency: i.currency || '',
    date: i.date || '',
    month: String(i.date || '').slice(0, 7),
    billingCycle: i.billing_cycle || 'unknown',
    seats: i.seats ?? null
  }}));

// ===== Subscription Leak Detection Engine =====
const cfg = $('Config').first().json;
const unusedDays = Number(cfg.unusedDays) || 30;
const minUtil = Number(cfg.minSeatUtilization) || 0.8;
const currency = cfg.currency || 'USD';
const today = new Date();

const num = v => { const n = parseFloat(String(v ?? '').replace(/[^0-9.\-]/g, '')); return isNaN(n) ? 0 : n; };
const clean = s => String(s || '').toLowerCase().replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
const r2 = n => Math.round((Number(n) || 0) * 100) / 100;
const daysSince = d => { const t = new Date(d); return isNaN(t) ? null : Math.floor((today - t) / 86400000); };
const safeAll = name => { try { return $(name).all().map(i => i.json); } catch (e) { return []; } };
const DEAD = ['cancelled', 'canceled', 'inactive', 'terminated'];

const cardTxns  = safeAll('Normalize Card Transactions').filter(t => t.merchant && t.amount > 0);
const invoices  = safeAll('Parse Invoice Data').filter(t => t.vendor);
const inventory = safeAll('Read SaaS Inventory').filter(r => r.tool);

// ---------- Build tool registry from inventory ----------
const tools = inventory.map(r => ({
  name: String(r.tool).trim(),
  aliases: [r.tool, ...String(r.aliases || '').split(/[,;|]/)].map(clean).filter(a => a.length >= 3),
  category: String(r.category || '').trim(),
  owner: r.owner || '',
  seats: num(r.seats_purchased),
  active: (r.active_users === '' || r.active_users == null) ? null : num(r.active_users),
  lastActive: r.last_active_date || '',
  listedMonthly: num(r.monthly_cost),
  costPerSeat: num(r.cost_per_seat),
  billingCycle: clean(r.billing_cycle) || 'monthly',
  renewal: r.renewal_date || '',
  status: clean(r.status) || 'active',
  charges: [],
  monthlyCost: 0
}));

const matchTool = text => {
  const t = ' ' + clean(text) + ' ';
  let best = null, len = 0;
  for (const tool of tools) for (const a of tool.aliases) {
    if ((t.includes(' ' + a + ' ') || (a.length >= 5 && t.includes(a))) && a.length > len) { best = tool; len = a.length; }
  }
  return best;
};

// ---------- Attach every charge to a tool (or to "unmatched") ----------
const unmatched = {};
const addCharge = c => {
  const tool = matchTool(c.text);
  if (tool) { tool.charges.push(c); return; }
  const key = clean(c.text).split(' ').slice(0, 2).join(' ') || 'unknown';
  (unmatched[key] = unmatched[key] || { key, label: c.label, charges: [] }).charges.push(c);
};
cardTxns.forEach(t => addCharge({ source: 'card', date: t.date, month: t.month, amount: t.amount, text: `${t.merchant} ${t.merchantRaw}`, label: t.merchantRaw }));
invoices.forEach(i => addCharge({ source: 'invoice', date: i.date, month: i.month, amount: i.amount, text: `${i.vendor} ${i.product}`, label: i.vendor, seats: i.seats, cycle: i.billingCycle }));

const findings = [];
const add = f => findings.push({ estMonthlySavings: 0, ...f });

// ---------- Per-tool checks ----------
for (const tool of tools) {
  const cardC = tool.charges.filter(c => c.source === 'card');
  const invC  = tool.charges.filter(c => c.source === 'invoice');
  const basis = (cardC.length ? cardC : invC).filter(c => c.amount > 0).sort((a, b) => String(a.date).localeCompare(String(b.date)));
  const latest = basis[basis.length - 1];
  const annual = /^(annual|year)/.test(tool.billingCycle);
  const actualMonthly = latest ? (annual ? latest.amount / 12 : latest.amount) : 0;
  tool.monthlyCost = actualMonthly || tool.listedMonthly || (tool.seats * tool.costPerSeat);
  const perSeat = tool.costPerSeat || (tool.seats ? tool.monthlyCost / tool.seats : 0);
  const base = { tool: tool.name, category: tool.category, owner: tool.owner };

  // 1) Zombie: cancelled in inventory but still billed
  if (DEAD.includes(tool.status)) {
    if (latest) add({ ...base, type: 'ZOMBIE_CHARGE', severity: 'high',
      detail: `Marked "${tool.status}" in inventory but still billed ${basis.length} time(s); latest ${currency} ${latest.amount} on ${latest.date}.`,
      estMonthlySavings: r2(actualMonthly), suggestedAction: 'Confirm cancellation with vendor and request a refund' });
    continue;
  }

  // 2) Duplicate charges in the same month
  const byMonth = {};
  cardC.forEach(c => { if (c.month) (byMonth[c.month] = byMonth[c.month] || []).push(c); });
  for (const [m, list] of Object.entries(byMonth)) {
    if (list.length < 2) continue;
    const s = [...list].sort((a, b) => a.amount - b.amount);
    const dupes = [];
    for (let i = 1; i < s.length; i++) if (Math.abs(s[i].amount - s[i - 1].amount) <= Math.max(1, s[i].amount * 0.05)) dupes.push(s[i]);
    if (dupes.length) add({ ...base, type: 'DUPLICATE_CHARGE', severity: 'high',
      detail: `${list.length} similar charges in ${m}: ${list.map(c => `${c.date} ${currency} ${c.amount} (${c.label})`).join('; ')}`,
      estMonthlySavings: r2(dupes.reduce((a, c) => a + c.amount, 0)),
      suggestedAction: 'Check for duplicate accounts / workspaces and consolidate billing' });
  }

  // 3) Unused tool  |  4) Seat waste
  const idle = tool.lastActive ? daysSince(tool.lastActive) : null;
  if (tool.active === 0 || (idle !== null && idle > unusedDays)) {
    add({ ...base, type: 'UNUSED_TOOL', severity: 'high',
      detail: tool.active === 0 ? `0 active users on ${tool.seats || '?'} paid seats.` : `No activity for ${idle} days (last active ${tool.lastActive}).`,
      estMonthlySavings: r2(tool.monthlyCost),
      suggestedAction: 'Cancel before next renewal' + (tool.renewal ? ` (${tool.renewal})` : '') });
  } else if (tool.seats > 0 && tool.active !== null && tool.active < tool.seats) {
    const util = tool.active / tool.seats;
    if (util < minUtil) {
      const wasted = tool.seats - tool.active;
      add({ ...base, type: 'SEAT_WASTE', severity: util < 0.5 ? 'high' : 'medium',
        detail: `${tool.active}/${tool.seats} seats in use (${Math.round(util * 100)}%) - ${wasted} idle seats at ~${currency} ${r2(perSeat)}/seat.`,
        estMonthlySavings: r2(wasted * perSeat), suggestedAction: `Reduce plan to ${tool.active} seats` });
    }
  }

  // 5) Invoice bills more seats than inventory says you own
  const invSeats = invC.filter(c => num(c.seats) > 0).sort((a, b) => String(a.date).localeCompare(String(b.date)));
  if (invSeats.length) {
    const billed = num(invSeats[invSeats.length - 1].seats);
    const ref = tool.active !== null ? tool.active : tool.seats;
    if (ref && billed > ref) add({ ...base, type: 'SEAT_MISMATCH', severity: 'medium',
      detail: `Latest invoice bills ${billed} seats, but inventory shows ${tool.seats} purchased / ${tool.active ?? '?'} active.`,
      estMonthlySavings: r2((billed - ref) * perSeat), suggestedAction: 'Reconcile seat count with vendor admin console' });
  }

  // 6) Price creep
  if (basis.length >= 2) {
    const prev = basis[basis.length - 2];
    if (latest.month !== prev.month && latest.amount > prev.amount * 1.1) add({ ...base, type: 'PRICE_INCREASE', severity: 'medium',
      detail: `Charge rose from ${currency} ${prev.amount} (${prev.date}) to ${currency} ${latest.amount} (${latest.date}), +${Math.round((latest.amount / prev.amount - 1) * 100)}%.`,
      estMonthlySavings: r2(annual ? (latest.amount - prev.amount) / 12 : latest.amount - prev.amount),
      suggestedAction: 'Review plan / add-on changes; negotiate or downgrade' });
  }

  // 7) Actual billing vs what the inventory says it should cost
  if (tool.listedMonthly && actualMonthly && Math.abs(actualMonthly - tool.listedMonthly) / tool.listedMonthly > 0.15) add({ ...base, type: 'BILLING_MISMATCH', severity: 'low',
    detail: `Inventory lists ${currency} ${tool.listedMonthly}/mo, actually billed ~${currency} ${r2(actualMonthly)}/mo.`,
    estMonthlySavings: r2(Math.max(0, actualMonthly - tool.listedMonthly)), suggestedAction: 'Update inventory or dispute the difference' });
}

// ---------- 8) Overlapping tools in the same category ----------
const byCat = {};
tools.filter(t => t.category && !DEAD.includes(t.status)).forEach(t => (byCat[t.category.toLowerCase()] = byCat[t.category.toLowerCase()] || []).push(t));
for (const list of Object.values(byCat)) {
  if (list.length < 2) continue;
  const keeper = [...list].sort((a, b) => (b.active ?? 0) - (a.active ?? 0) || b.monthlyCost - a.monthlyCost)[0];
  add({ tool: list.map(t => t.name).join(' + '), category: list[0].category,
    owner: [...new Set(list.map(t => t.owner).filter(Boolean))].join(', '),
    type: 'OVERLAPPING_TOOLS', severity: 'medium',
    detail: `${list.length} tools in "${list[0].category}": ${list.map(t => `${t.name} (${currency} ${r2(t.monthlyCost)}/mo, ${t.active ?? '?'} users)`).join(', ')}. Most-used: ${keeper.name}.`,
    estMonthlySavings: r2(list.filter(t => t !== keeper).reduce((a, t) => a + t.monthlyCost, 0)),
    suggestedAction: `Consolidate onto ${keeper.name}` });
}

// ---------- 9) Shadow subscriptions (recurring spend not in inventory) ----------
for (const u of Object.values(unmatched)) {
  const months = new Set(u.charges.map(c => c.month).filter(Boolean));
  const amounts = u.charges.map(c => c.amount).filter(a => a > 0);
  if (!amounts.length) continue;
  const fromInvoice = u.charges.some(c => c.source === 'invoice');
  const recurring = months.size >= 2 && (Math.max(...amounts) - Math.min(...amounts)) <= Math.max(2, Math.max(...amounts) * 0.2);
  if (!recurring && !fromInvoice) continue;
  const latest = [...u.charges].sort((a, b) => String(a.date).localeCompare(String(b.date))).pop();
  add({ tool: u.label, category: 'Unknown', owner: '', type: 'SHADOW_SUBSCRIPTION', severity: recurring ? 'medium' : 'low',
    detail: `Not in SaaS inventory. ${u.charges.length} charge(s) across ${months.size} month(s); latest ${currency} ${latest.amount} on ${latest.date || 'n/a'}.`,
    estMonthlySavings: r2(latest.amount), suggestedAction: 'Identify owner - add to inventory or cancel' });
}

const sevRank = { high: 0, medium: 1, low: 2 };
findings.sort((a, b) => sevRank[a.severity] - sevRank[b.severity] || b.estMonthlySavings - a.estMonthlySavings);
const potential = r2(findings.reduce((a, f) => a + f.estMonthlySavings, 0));

return [{ json: {
  runDate: today.toISOString().slice(0, 10),
  currency,
  totals: {
    cardTransactions: cardTxns.length,
    invoices: invoices.length,
    inventoryTools: tools.length,
    trackedMonthlySpend: r2(tools.filter(t => !DEAD.includes(t.status)).reduce((a, t) => a + t.monthlyCost, 0))
  },
  findingsCount: findings.length,
  potentialMonthlySavings: potential,
  potentialAnnualSavings: r2(potential * 12),
  findings
}}];

