// Merges the AI cancellation plan with the raw detection results.
const det = $('Detect Leaks').first().json;
const num = v => { const n = parseFloat(String(v ?? '').replace(/[^0-9.\-]/g, '')); return isNaN(n) ? 0 : n; };
let c = $input.first()?.json?.message?.content ?? $input.first()?.json?.content ?? {};
if (typeof c === 'string') {
  try { c = JSON.parse(c.replace(/```json|```/g, '').trim()); }
  catch (e) { c = { executive_summary: c, recommendations: [] }; }
}
const recs = Array.isArray(c.recommendations) ? c.recommendations : [];
const monthly = num(c.total_est_monthly_savings) ||
  recs.filter(r => !['keep', 'ignore'].includes(String(r.action).toLowerCase())).reduce((a, r) => a + num(r.est_monthly_savings), 0) ||
  det.potentialMonthlySavings;
const m = Math.round(monthly * 100) / 100;
return [{ json: {
  ...det,
  summary: c.executive_summary || '',
  recommendations: recs,
  confirmedMonthlySavings: m,
  confirmedAnnualSavings: Math.round(m * 12 * 100) / 100
}}];

// One Google Sheets row per finding, enriched with the AI recommendation.
const d = $input.first().json;
const recs = d.recommendations || [];
const lc = s => String(s || '').toLowerCase().trim();
const recFor = tool => recs.find(r => lc(r.tool) === lc(tool)) ||
  recs.find(r => r.tool && (lc(tool).includes(lc(r.tool)) || lc(r.tool).includes(lc(tool)))) || {};
return d.findings.map((f, i) => {
  const r = recFor(f.tool);
  return { json: {
    run_date: d.runDate,
    finding_id: `${d.runDate}-${String(i + 1).padStart(3, '0')}`,
    type: f.type,
    severity: f.severity,
    tool: f.tool,
    category: f.category,
    owner: f.owner,
    detail: f.detail,
    est_monthly_savings: f.estMonthlySavings,
    currency: d.currency,
    recommended_action: r.action || f.suggestedAction,
    priority: r.priority || f.severity,
    next_step: r.next_step || f.suggestedAction,
    status: 'Open'
  }};
});

